export default function Obras(){return <main style={{padding:32,fontFamily:'Arial'}}><h1>Obras</h1><p>Controlo de áreas, custos previstos vs. reais, equipas, materiais e rentabilidade.</p><button>Nova obra</button><table style={{marginTop:24,width:'100%',borderCollapse:'collapse'}}><thead><tr><th align="left">Obra</th><th align="left">Cliente</th><th>Área</th><th>Valor</th><th>Margem</th><th>Estado</th></tr></thead><tbody>{obras.map(o=><tr key={o[0]}>{o.map((x,i)=><td key={i} style={{padding:12,borderBottom:'1px solid #ddd',textAlign:i>1?'center':'left'}}>{x}</td>)}</tr>)}</tbody></table></main>}
